const { Writable } = require("node:stream");

function denied(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function responseReaderAttempt(response) {
  return deniedAsync(async () => {
    const reader = response.body.getReader();
    try {
      await reader.read();
    } finally {
      reader.releaseLock();
    }
  });
}

function responseByobReaderAttempt(response) {
  return deniedAsync(async () => {
    const reader = response.body.getReader({ mode: "byob" });
    try {
      await reader.read(new Uint8Array(64));
    } finally {
      reader.releaseLock();
    }
  });
}

function responseIteratorAttempt(response) {
  return deniedAsync(async () => {
    const iterator = response.body.values();
    try {
      await iterator.next();
    } finally {
      await iterator.return?.();
    }
  });
}

function responsePipeThroughAttempt(response) {
  return deniedAsync(async () => {
    const output = response.body.pipeThrough(new TransformStream());
    const reader = output.getReader();
    try {
      await reader.read();
    } finally {
      reader.releaseLock();
    }
  });
}

function nodeSocketIteratorAttempt(socket) {
  return deniedAsync(async () => {
    const iterator = socket[Symbol.asyncIterator]();
    try {
      await iterator.next();
    } finally {
      await iterator.return?.();
    }
  });
}

async function deniedAsync(operation) {
  try {
    await operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function websocketAttempt(url) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    try {
      const socket = new WebSocket(url);
      socket.addEventListener("open", () => {
        socket.close();
        finish("ALLOWED");
      }, { once: true });
      socket.addEventListener("error", () => finish("DENIED"), { once: true });
      setTimeout(() => finish("DENIED"), 1000);
    } catch {
      finish("DENIED");
    }
  });
}

function nodeSocketAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    socket.once("error", () => finish("DENIED"));
    socket.write("GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n", (error) =>
      finish(error ? "DENIED" : "ALLOWED")
    );
    setTimeout(() => finish("DENIED"), 1000);
  });
}

function nodeSocketReadAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    try {
      socket.once("data", () => finish("ALLOWED"));
      socket.once("error", () => finish("DENIED"));
      socket.resume();
    } catch {
      finish("DENIED");
    }
    setTimeout(() => finish("DENIED"), 1000);
  });
}

function websocketReadAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    socket.addEventListener("message", () => finish("ALLOWED"), { once: true });
    socket.addEventListener("error", () => finish("DENIED"), { once: true });
    socket.addEventListener("close", () => finish("DENIED"), { once: true });
    setTimeout(() => finish("DENIED"), 1000);
  });
}

async function probeEndpointPassage(resources) {
  return {
    directFetch: await deniedAsync(() => fetch(resources.httpUrl)),
    directDnsFetch: await deniedAsync(() => fetch(resources.dnsHttpUrl)),
    directWebSocket: await websocketAttempt(resources.wsUrl),
    directDnsWebSocket: await websocketAttempt(resources.dnsWsUrl),
    passedDenoConn: await deniedAsync(() => resources.denoConn.write(
      new TextEncoder().encode("GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n"),
    )),
    passedDenoConnRead: await deniedAsync(() => resources.readDenoConn.read(
      new Uint8Array(4096),
    )),
    passedNodeSocket: await nodeSocketAttempt(resources.nodeSocket),
    passedNodeSocketRead: await nodeSocketReadAttempt(resources.readNodeSocket),
    passedNodeSocketIterator: await nodeSocketIteratorAttempt(
      resources.iteratorNodeSocket,
    ),
    passedNodeSocketPipe: denied(() =>
      resources.pipeNodeSocket.pipe(new Writable({
        write(_chunk, _encoding, callback) {
          callback();
        },
      }))
    ),
    passedNodeToWebRead: await deniedAsync(async () => {
      const reader = resources.nodeToWebStream.getReader();
      try {
        await reader.read();
      } finally {
        reader.releaseLock();
      }
    }),
    passedWebToNodeRead: denied(() => resources.webToNodeStream.read()),
    passedResponse: await deniedAsync(() => resources.rootResponse.text()),
    passedDnsResponse: await deniedAsync(() => resources.rootDnsResponse.text()),
    passedResponseReader: await responseReaderAttempt(
      resources.readerResponse,
    ),
    passedResponseByobReader: await responseByobReaderAttempt(
      resources.byobResponse,
    ),
    passedResponseClone: denied(() => resources.cloneResponse.clone()),
    passedResponseTee: denied(() => resources.teeResponse.body.tee()),
    passedResponseIterator: await responseIteratorAttempt(
      resources.iteratorResponse,
    ),
    passedResponsePipeTo: await deniedAsync(() =>
      resources.pipeToResponse.body.pipeTo(new WritableStream())
    ),
    passedResponsePipeThrough: await responsePipeThroughAttempt(
      resources.pipeThroughResponse,
    ),
    passedResponseTransfer: denied(() => {
      const body = resources.transferResponse.body;
      structuredClone(body, { transfer: [body] });
    }),
    ordinaryResponse: await deniedAsync(() =>
      new Response("ordinary-response").text()
    ),
    passedWebSocket: denied(() => resources.rootWebSocket.send(
      JSON.stringify({ id: 1, method: "Runtime.enable" }),
    )),
    passedDnsWebSocket: denied(() => resources.rootDnsWebSocket.send(
      JSON.stringify({ id: 2, method: "Runtime.enable" }),
    )),
    passedWebSocketRead: await websocketReadAttempt(resources.readWebSocket),
  };
}

probeEndpointPassage.afterClose = (response) =>
  deniedAsync(() => response.text());

module.exports = probeEndpointPassage;
